import React, { useState, useEffect } from 'react';
import { Mail, Lock, ArrowRight, X, ArrowLeft, ShieldCheck, Zap, ShieldAlert, Fingerprint } from 'lucide-react';

const Login = ({ isOpen, onClose, onLogin }) => {
  const [isFlipped, setIsFlipped] = useState(false);
  const [loginView, setLoginView] = useState('login');
  const [loginOtpSent, setLoginOtpSent] = useState(false);

  // Sync with your provided logic for opening/closing
  useEffect(() => {
    if (!isOpen) {
      setIsFlipped(false);
      setLoginView('login');
      setLoginOtpSent(false);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const goToRecovery = () => {
    setIsFlipped(true);
  };

  const goToSignin = () => {
    setIsFlipped(false);
    setLoginView('login');
    setLoginOtpSent(false);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#47510B]/50 backdrop-blur-xl p-4 font-sans">
      <div className="flip-container w-full max-w-[420px] h-[620px] animate-slide-up">
        <div className={`flip-inner ${isFlipped ? 'is-flipped' : ''}`}>

          {/* --- FRONT SIDE: ADMIN CORE ACCESS --- */}
          <div className="flip-front bg-[#FDFAD8] border-[6px] border-[#47510B] rounded-[50px] shadow-[0_24px_0_0_#47510B] p-10 flex flex-col justify-between text-[#47510B] relative overflow-hidden">

            {/* Tactical Scanline (From your CSS) */}
            <div className="absolute inset-0 pointer-events-none opacity-10">
               <div className="animate-scan" />
            </div>

            <div className="flex justify-between items-center relative z-10">
              <div className="bg-[#FF5B03] p-3 rounded-2xl shadow-[4px_4px_0_0_#47510B] border-2 border-[#47510B]">
                <ShieldCheck size={28} className="text-[#FDFAD8]" />
              </div>
              <button onClick={onClose} className="hover:rotate-90 transition-transform p-2">
                <X size={32} strokeWidth={3} />
              </button>
            </div>

            <div className="mt-4 relative z-10">
              <h2 className="text-5xl font-black uppercase italic tracking-tighter leading-[0.85]">
                {loginView === 'login' ? <>COMMAND<br /><span className="text-[#FF5B03]">PORTAL</span></> : <>BYPASS<br /><span className="text-[#AB1717]">NODE</span></>}
              </h2>
              <div className="flex gap-2 mt-4">
                <div className="h-2 w-12 bg-[#FF5B03] rounded-full" />
                <div className="h-2 w-3 bg-[#47510B] rounded-full opacity-30" />
              </div>
            </div>

            {loginView === 'login' && (
              <div className="space-y-5 mt-6 relative z-10">
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60 ml-1">ADMIN_IDENTIFIER</label>
                  <div className="relative group">
                    <Fingerprint className="absolute left-5 top-5 text-[#47510B] opacity-30 group-focus-within:opacity-100 transition-opacity" size={20} />
                    <input type="email" placeholder="root@trash2track.io" className="w-full bg-white border-4 border-[#47510B] p-5 pl-14 rounded-[28px] font-black text-sm outline-none focus:ring-8 ring-[#FF5B03]/10 focus:bg-[#CAD23C]/5 transition-all" />
                  </div>
                </div>

                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60 ml-1">SECURITY_KEY</label>
                  <div className="relative group">
                    <Lock className="absolute left-5 top-5 text-[#47510B] opacity-30 group-focus-within:opacity-100 transition-opacity" size={20} />
                    <input type="password" placeholder="••••••••" className="w-full bg-white border-4 border-[#47510B] p-5 pl-14 rounded-[28px] font-black text-sm outline-none focus:ring-8 ring-[#FF5B03]/10 focus:bg-[#CAD23C]/5 transition-all" />
                  </div>
                </div>

                <button onClick={() => setLoginView('forgot')} className="text-[11px] font-black text-[#AB1717] uppercase tracking-widest ml-1 hover:underline underline-offset-4">Emergency Recovery?</button>

                <button onClick={onLogin} className="w-full bg-[#FF5B03] text-[#FDFAD8] font-black p-6 rounded-[30px] flex items-center justify-center gap-4 shadow-[0_10px_0_0_#AB1717] active:translate-y-2 active:shadow-none transition-all uppercase text-2xl italic tracking-tighter border-2 border-[#47510B] group">
                  INITIALIZE <ArrowRight size={32} strokeWidth={3} className="group-hover:translate-x-2 transition-transform" />
                </button>
              </div>
            )}

            {loginView === 'forgot' && (
              <div className="space-y-5 mt-6 relative z-10 animate-slide-up">
                <div className="p-4 bg-[#AB1717]/5 border-2 border-dashed border-[#AB1717]/30 rounded-2xl">
                  <p className="text-[10px] font-bold text-[#AB1717] text-center leading-tight uppercase">Manual override requires secondary verification node.</p>
                </div>
                <input type="email" placeholder="REGISTERED_EMAIL" className="w-full bg-white border-4 border-[#47510B] p-5 rounded-[28px] font-black text-sm outline-none" />

                {loginOtpSent && (
                  <div className="flex gap-2 justify-between animate-slide-up">
                    {[1, 2, 3, 4].map(i => <input key={i} type="text" maxLength="1" className="w-16 h-20 bg-white border-4 border-[#47510B] rounded-2xl text-center font-black text-2xl focus:bg-[#CAD23C]/20 transition-colors outline-none" />)}
                  </div>
                )}

                <button
                  onClick={() => loginOtpSent ? onLogin() : setLoginOtpSent(true)}
                  className="w-full bg-[#47510B] text-[#CAD23C] font-black p-6 rounded-[30px] shadow-[0_10px_0_0_#2A3106] active:translate-y-2 active:shadow-none uppercase text-xl italic transition-all"
                >
                  {loginOtpSent ? 'Verify Override' : 'Request Token'}
                </button>
                <button onClick={() => { setLoginView('login'); setLoginOtpSent(false); }} className="w-full text-center text-[11px] font-black uppercase opacity-40 hover:opacity-100 tracking-[0.2em]">Return to Core</button>
              </div>
            )}

            <div className="text-center pt-4 opacity-20 border-t-2 border-[#47510B]/10">
              <button onClick={goToRecovery} className="font-black text-[12px] tracking-[0.3em] uppercase hover:opacity-100">
                SYSTEM_PROTOCOLS <span className="text-[#FF5B03]">READ_ONLY</span>
              </button>
            </div>
          </div>

          {/* --- BACK SIDE: SYSTEM PROTOCOLS --- */}
          <div className="flip-back bg-[#CAD23C] border-[6px] border-[#47510B] rounded-[50px] shadow-[0_24px_0_0_#47510B] p-10 flex flex-col h-full text-[#47510B]">
            <div className="flex justify-between items-center mb-10 relative z-10">
              <button onClick={goToSignin} className="flex items-center gap-2 font-black text-[16px] tracking-tighter uppercase italic">
                <ArrowLeft size={28} strokeWidth={3} /> Return
              </button>
              <Zap size={28} className="text-[#FF5B03] animate-pulse" />
            </div>

            <div className="flex-1 space-y-8 relative z-10">
              <div>
                <h2 className="text-4xl font-black text-[#47510B] uppercase italic tracking-tighter leading-none">Security<br />Policy</h2>
                <div className="h-2 w-16 bg-[#FF5B03] mt-4" />
              </div>

              <div className="space-y-4">
                <div className="flex items-start gap-4 p-5 bg-white/40 border-2 border-[#47510B] rounded-3xl">
                   <ShieldAlert size={42} className="shrink-0 text-[#AB1717]" />
                   <p className="text-[11px] font-black leading-tight uppercase">Authorization required. Unauthorized access to the garbage management network is a violation of municipal code 404.</p>
                </div>

                <div className="p-5 border-2 border-[#47510B] rounded-3xl bg-[#FDFAD8]/40">
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-[10px] font-black uppercase opacity-60">System Health</span>
                    <span className="text-[10px] font-black text-[#47510B] bg-[#CAD23C] px-2 rounded">Optimal</span>
                  </div>
                  <div className="w-full h-3 bg-[#47510B]/20 rounded-full overflow-hidden">
                    <div className="w-[98%] h-full bg-[#47510B]" />
                  </div>
                </div>
              </div>
            </div>

            <button onClick={goToSignin} className="w-full bg-[#47510B] text-white py-6 rounded-[30px] font-black uppercase italic text-xl shadow-[0_8px_0_0_#2A3106] active:translate-y-2 active:shadow-none transition-all mt-6">
              Acknowledge Entry
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
